/**
 * The measured tables (palette/restHeights.ts, restGrids.ts, hangGrids.ts, coverHoles.ts), generated by
 * `npm run render -- rests` from the game's meshes: what each entry was measured against, the rule that applies an
 * entry only to the piece it was measured on, and the content hash that tells a regenerated table from a hand-edited one.
 *
 * An entry is keyed by asset id, but a game update may reshape a piece and keep its id, and a palette import may run
 * where TaleSpire is not installed: the palette then carries the new collider while the table still holds the old
 * reading. So each entry records the collider it was read against (the install's, at the time) and an entry is applied
 * only while the collider a piece is built with (its palette's `geom`) is that one; otherwise the piece is treated as
 * never measured (its box top, whole cover, no grid), and the core tests name it stale until the tables are re-run.
 */
import type { PaletteVariant } from "../contracts/compiler";
import { h64hex } from "../util/hash";

/** What every measured entry records besides its reading. */
export interface Measured {
  /** The piece's name when it was read (for people reading the table). */
  readonly name: string;
  /** The collider the reading was taken against (x, y, z in tiles): the install's, which the reading's frame is. */
  readonly size: readonly [number, number, number];
  /**
   * The mesh's identity when it was read (FNV-1a 32 over its vertex and index data, hex): a re-run's diff shows which
   * pieces the game changed. Core cannot check it (tests never open the install).
   */
  readonly mesh: string;
}

/** palette/restHeights.ts: the one rest height above the collider's bottom (tiles). */
export interface MeasuredRest extends Measured {
  readonly rest: number;
}

/** palette/restGrids.ts and hangGrids.ts: a grid over the outline, as palette/restGrid.ts parses it. */
export interface MeasuredGrid extends Measured {
  readonly grid: string;
}

/** palette/coverHoles.ts: the largest open patch of the top (tiles²). */
export interface MeasuredHole extends Measured {
  readonly hole: number;
}

/** A collider whose size differs from the measured one by more than this on any axis (tiles) is another piece. */
export const MEASURED_SIZE_TOLERANCE = 0.01;

/** The part of a piece's collider the guard compares. */
export type MeasuredCollider = Pick<PaletteVariant["geom"], "size">;

/** Was `m` read against this collider? */
export function fitsMeasured(m: Measured, geom: MeasuredCollider): boolean {
  const [x, y, z] = m.size;
  return (
    Math.abs(x - geom.size.x) <= MEASURED_SIZE_TOLERANCE &&
    Math.abs(y - geom.size.y) <= MEASURED_SIZE_TOLERANCE &&
    Math.abs(z - geom.size.z) <= MEASURED_SIZE_TOLERANCE
  );
}

/** A table's entry for `asset` when it was measured on the collider the piece is built with; else undefined. */
export function measuredEntry<T extends Measured>(
  table: Readonly<Record<string, T>>,
  asset: string,
  geom: MeasuredCollider,
): T | undefined {
  const id = asset.toLowerCase();
  const m = Object.hasOwn(table, id) ? table[id] : undefined;
  return m !== undefined && fitsMeasured(m, geom) ? m : undefined;
}

/** The pieces `table` holds a reading of that no longer fits their collider (a re-run of the measuring is due). */
export function staleMeasured<T extends Measured>(
  table: Readonly<Record<string, T>>,
  pieces: ReadonlyArray<{ readonly asset: string; readonly name: string; readonly geom: MeasuredCollider }>,
): string[] {
  return pieces
    .filter((p) => Object.hasOwn(table, p.asset) && measuredEntry(table, p.asset, p.geom) === undefined)
    .map((p) => {
      const m = table[p.asset];
      const was = m ? m.size.join(" x ") : "?";
      return `${p.name} (${p.asset}): measured on ${was}, the palette's is ${String(p.geom.size.x)} x ${String(p.geom.size.y)} x ${String(p.geom.size.z)}`;
    });
}

/** The header line of a generated table that states its body's hash. */
export const TABLE_HASH_PREFIX = " * Content hash ";

/** The end of a generated table's header comment: the body is everything after it. */
const HEADER_END = "\n */\n";

/** The hash a generated table's header states for its body (FNV-1a 64 over the text after the header comment). */
export function tableBodyHash(body: string): string {
  return h64hex(body);
}

/**
 * A generated table's text split into the hash its header states (null when it states none) and its body, and whether
 * the body still has that hash: false is a hand edit (or a table written by an older script).
 */
export function checkTableHash(text: string): { stated: string | null; actual: string; ok: boolean } {
  const end = text.indexOf(HEADER_END);
  const header = end < 0 ? "" : text.slice(0, end);
  const body = end < 0 ? text : text.slice(end + HEADER_END.length);
  const line = header.split("\n").find((l) => l.startsWith(TABLE_HASH_PREFIX));
  const stated = line ? (/[0-9a-f]{16}/.exec(line.slice(TABLE_HASH_PREFIX.length))?.[0] ?? null) : null;
  const actual = tableBodyHash(body);
  return { stated, actual, ok: stated === actual };
}
